import test from'node:test';import assert from'node:assert/strict';import{make,validate,apply}from'./state.js';import{portable,parse}from'../creative-kit/state.js';
test('forks retain the original benefit and explain which concern generated them',()=>{const w=make();const benefit=w.benefit;apply(w,{type:'fork',id:'d2',concern:'c2',method:'exposure'});assert.equal(w.benefit,benefit);assert.deepEqual(w.designs[1].concerns,['c2']);assert.throws(()=>apply(w,{type:'remove-concern',id:'c2'}));});
test('changed concerns retain designs but request review, and portable references survive',()=>{const w=make();const mechanism=w.designs[0].mechanism;apply(w,{type:'edit',collection:'concerns',item:'c1',field:'concern',value:'Changed concern'});assert.equal(w.designs[0].stale,true);assert.equal(w.designs[0].mechanism,mechanism);assert.deepEqual(parse(portable(w,'objections',validate),'objections',validate),w);w.designs[0].concerns=['missing'];assert.throws(()=>validate(w));});
